tool_input.command:
cat > migrations/002_webhooks.sql <<'EOF'
-- Payment provider webhook events already processed (dedupe on redelivery).
create table webhook_events (
  id text primary key,
  received_at timestamptz not null default now()
);

-- Timestamp (provider `created`) of the last webhook applied to the order; older events are ignored.
alter table orders add column last_event_at bigint;
EOF
python3 - <<'EOF'
p='src/app.ts'
s=open(p).read()
s=s.replace('import { pool } from "./db.ts";','import { createHmac, timingSafeEqual } from "node:crypto";\nimport { pool } from "./db.ts";\nimport { webhookSecret } from "./payments.ts";',1)
s=s.replace('''declare global {
  namespace Express {''','''declare global {
  namespace Express {
    interface Request {
      rawBody?: Buffer;
    }''',1)
s=s.replace('  app.use(express.json());','''  app.use(express.json({ verify: (req, _res, buf) => { (req as Request).rawBody = buf; } }));''',1)
s=s.replace('''  app.use(auth);
''','''  const statusByType: Record<string, string> = {
    "charge.succeeded": "paid",
    "charge.failed": "failed",
    "charge.refunded": "refunded",
  };

  // Called by the payment provider, so it uses the signature instead of a bearer token.
  app.post("/webhooks/payments", async (req, res) => {
    const signature = req.get("provider-signature");
    const expected = createHmac("sha256", webhookSecret).update(req.rawBody ?? Buffer.alloc(0)).digest();
    const given = signature && /^[0-9a-f]{64}$/i.test(signature) ? Buffer.from(signature, "hex") : null;
    if (!given || !timingSafeEqual(given, expected)) return sendError(res, 401, "invalid_signature", "Invalid signature");

    const { id, type, paymentId, created } = req.body ?? {};
    const status = typeof type === "string" ? statusByType[type] : undefined;
    if (typeof id !== "string" || typeof paymentId !== "string" || !Number.isInteger(created) || !status) {
      return sendError(res, 400, "invalid_event", "Invalid or unsupported event");
    }

    const client = await pool.connect();
    try {
      await client.query("begin");
      const inserted = await client.query("insert into webhook_events (id) values ($1) on conflict do nothing", [id]);
      if (inserted.rowCount === 0) {
        await client.query("rollback");
        return void res.json({ ok: true, duplicate: true });
      }
      // Events can arrive out of order: only apply one newer than the last applied for this order.
      const updated = await client.query(
        `update orders set status = $1, last_event_at = $2
         where payment_id = $3 and (last_event_at is null or last_event_at < $2)`,
        [status, created, paymentId],
      );
      if (updated.rowCount === 0) {
        const exists = await client.query("select 1 from orders where payment_id = $1", [paymentId]);
        if (exists.rowCount === 0) {
          // Unknown order: roll back (event not recorded) so the provider's retry can succeed later.
          await client.query("rollback");
          return sendError(res, 404, "not_found", "No order for this payment");
        }
      }
      await client.query("commit");
      res.json({ ok: true });
    } catch (err) {
      await client.query("rollback").catch(() => {});
      throw err;
    } finally {
      client.release();
    }
  });

  app.use(auth);
''',1)
open(p,'w').write(s)
EOF
